// BSS-VS-Seq JS engine: chapter sequencer for Virtual Stargazing
// Loaded by src/Control Pages/BSS-VirtualStargazing/01-BSS-VS-LoadSeq.txt, generated by tools/wrap-js.sh.
// Setup runs the loader, so loading again resets the overrides to auto.
// Dark Matter JS is old ES5: use var and plain functions, no let/const/import.
// Do not put closing parentheses inside comments: older DM versions end the block there.
//
// Chapter 2 has conditional segments: Moon, planets, galactic core. This engine works out
// what is above the horizon from the PC clock and the Aoraki position, using its own low
// precision ephemeris, good to about 1 degree, so it needs no DM property. Then it runs the
// segment buttons one after the other.
// NOTE: it uses the PC clock, not the DM sky time. Setup sets the sky to real time, so they
// match. To test another time, use SetTestOffset with a number of hours, 0 to go back.
// NOTE: waits are in JS, so the Playlist Creator cannot render the chapter as a whole.

var running = 0;
var PAGE = "Control Mt Cook.Theater.BSS-VirtualStargazing.";
var LAT = -43.7357;
var LON = 170.0962;
var testOffsetHours = 0;

// Minimum altitude in degrees. auto uses these, on uses 0 = just above the horizon
var MIN_ALT = { Moon: 10, Planets: 10, Core: 15 };
var mode = { Moon: "auto", Planets: "auto", Core: "auto" };

// Segment lengths in seconds: keep equal to the Length in each button header
var LEN = {
    "Intro": 10.2,
    "Moon": 18.2,
    "Planets": 12.2,
    "Mercury": 11.2,
    "Venus": 11.2,
    "Mars": 11.2,
    "Jupiter": 11.2,
    "Saturn": 11.2,
    "PlanetsEnd": 4,
    "Stars": 51,
    "Core": 17.2,
    "Magellan": 37.2
};
var GAP = 0.5;
var PLANETS = ["Mercury", "Venus", "Mars", "Jupiter", "Saturn"];

// Play all: chapter buttons in order, with their lengths in seconds.
// Keep equal to the total on the last comment line of each chapter button.
// Chapter 2 has no length here: PlayShow runs its segments itself.
var CHAPTERS = [
    ["DarkSkies", 111.2],
    ["DistancesAndPerspective", 0],
    ["CelestialNav", 95.4],
    ["Constellations", 148.8],
    ["VirtualTelescope", 150.4],
    ["SouthernLights", 84.4],
    ["Moon", 223.4],
    ["SolarSystem", 144.2],
    ["MilkyWay", 172.4]
];

// ---------- DM helpers ----------

function dm(s) {
    DigitalSky.SendScript(s);
    DigitalSky.LogMessage(s);
}

function log(s) {
    DigitalSky.LogMessage("BSS-VS-Seq: " + s);
}

// Wait in small steps so Stop takes effect within half a second
function waitStep(n) {
    var t = 0;
    while (running && t < n) {
        DigitalSky.Wait(0.5);
        t = t + 0.5;
    }
}

function seg(name) {
    if (!running) return;
    dm(PAGE + "BSS-VS-Dist-" + name + ".Run()");
    waitStep(LEN[name] + GAP);
}

// ---------- astronomy ----------

var RAD = Math.PI / 180;

function sind(x) { return Math.sin(x * RAD); }
function cosd(x) { return Math.cos(x * RAD); }
function norm360(x) { x = x % 360; if (x < 0) x = x + 360; return x; }

// Days since J2000.0
function daysJ2000() {
    var ms = new Date().getTime() + testOffsetHours * 3600000;
    return ms / 86400000 + 2440587.5 - 2451545.0;
}

// Altitude in degrees of RA and Dec in degrees, for day number d
function altitude(ra, dec, d) {
    var lst = norm360(280.46061837 + 360.98564736629 * d + LON);
    var h = lst - ra;
    var s = sind(LAT) * sind(dec) + cosd(LAT) * cosd(dec) * cosd(h);
    return Math.asin(s) / RAD;
}

// Ecliptic J2000 x, y, z to RA and Dec in degrees
function eclToRaDec(x, y, z) {
    var eps = 23.43928;
    var xe = x;
    var ye = y * cosd(eps) - z * sind(eps);
    var ze = y * sind(eps) + z * cosd(eps);
    var ra = norm360(Math.atan2(ye, xe) / RAD);
    var dec = Math.atan2(ze, Math.sqrt(xe * xe + ye * ye)) / RAD;
    return { ra: ra, dec: dec };
}

// JPL approximate Keplerian elements, valid 1800-2050:
// a, e, I, L, long. perihelion, long. node, each value then rate per century
var ELEM = {
    Mercury: [0.38709927, 0.00000037, 0.20563593, 0.00001906, 7.00497902, -0.00594749,
              252.25032350, 149472.67411175, 77.45779628, 0.16047689, 48.33076593, -0.12534081],
    Venus:   [0.72333566, 0.00000390, 0.00677672, -0.00004107, 3.39467605, -0.00078890,
              181.97909950, 58517.81538729, 131.60246718, 0.00268329, 76.67984255, -0.27769418],
    Earth:   [1.00000261, 0.00000562, 0.01671123, -0.00004392, -0.00001531, -0.01294668,
              100.46457166, 35999.37244981, 102.93768193, 0.32327364, 0.0, 0.0],
    Mars:    [1.52371034, 0.00001847, 0.09339410, 0.00007882, 1.84969142, -0.00813131,
              -4.55343205, 19140.30268499, -23.94362959, 0.44441088, 49.55953891, -0.29257343],
    Jupiter: [5.20288700, -0.00011607, 0.04838624, -0.00013253, 1.30439695, -0.00183714,
              34.39644051, 3034.74612775, 14.72847983, 0.21252668, 100.47390909, 0.20469106],
    Saturn:  [9.53667594, -0.00125060, 0.05386179, -0.00050991, 2.48599187, 0.00193609,
              49.95424423, 1222.49362201, 92.59887831, -0.41897216, 113.66242448, -0.28867794]
};

// Heliocentric ecliptic position in AU
function helio(name, d) {
    var el = ELEM[name];
    var T = d / 36525;
    var a = el[0] + el[1] * T;
    var e = el[2] + el[3] * T;
    var I = el[4] + el[5] * T;
    var L = el[6] + el[7] * T;
    var wb = el[8] + el[9] * T;
    var node = el[10] + el[11] * T;
    var w = wb - node;
    var M = norm360(L - wb);
    if (M > 180) M = M - 360;
    // Kepler equation, degrees
    var ed = e / RAD;
    var E = M + ed * sind(M);
    for (var i = 0; i < 10; i++) {
        var dE = (M - (E - ed * sind(E))) / (1 - e * cosd(E));
        E = E + dE;
        if (Math.abs(dE) < 1e-6) break;
    }
    var xp = a * (cosd(E) - e);
    var yp = a * Math.sqrt(1 - e * e) * sind(E);
    var x = (cosd(w) * cosd(node) - sind(w) * sind(node) * cosd(I)) * xp +
            (-sind(w) * cosd(node) - cosd(w) * sind(node) * cosd(I)) * yp;
    var y = (cosd(w) * sind(node) + sind(w) * cosd(node) * cosd(I)) * xp +
            (-sind(w) * sind(node) + cosd(w) * cosd(node) * cosd(I)) * yp;
    var z = (sind(w) * sind(I)) * xp + (cosd(w) * sind(I)) * yp;
    return [x, y, z];
}

function planetAlt(name, d) {
    var p = helio(name, d);
    var e = helio("Earth", d);
    var rd = eclToRaDec(p[0] - e[0], p[1] - e[1], p[2] - e[2]);
    return altitude(rd.ra, rd.dec, d);
}

// Low precision Moon, Astronomical Almanac, about 0.3 degree: geocentric RA, Dec and parallax
function moonRaDec(d) {
    var T = d / 36525;
    var lam = 218.32 + 481267.881 * T
        + 6.29 * sind(135.0 + 477198.87 * T) - 1.27 * sind(259.3 - 413335.36 * T)
        + 0.66 * sind(235.7 + 890534.22 * T) + 0.21 * sind(269.9 + 954397.74 * T)
        - 0.19 * sind(357.5 + 35999.05 * T) - 0.11 * sind(186.5 + 966404.03 * T);
    var bet = 5.13 * sind(93.3 + 483202.02 * T) + 0.28 * sind(228.2 + 960400.89 * T)
        - 0.28 * sind(318.3 + 6003.15 * T) - 0.17 * sind(217.6 - 407332.21 * T);
    var par = 0.9508 + 0.0518 * cosd(135.0 + 477198.87 * T) + 0.0095 * cosd(259.3 - 413335.36 * T)
        + 0.0078 * cosd(235.7 + 890534.22 * T) + 0.0028 * cosd(269.9 + 954397.74 * T);
    var rd = eclToRaDec(cosd(bet) * cosd(lam), cosd(bet) * sind(lam), sind(bet));
    rd.par = par;
    return rd;
}

// Moon altitude, corrected for parallax
function moonAlt(d) {
    var rd = moonRaDec(d);
    var alt = altitude(rd.ra, rd.dec, d);
    return alt - rd.par * cosd(alt);
}

// Galactic centre, Sgr A* J2000
function coreAlt(d) {
    return altitude(266.4168, -29.0078, d);
}

// ---------- decisions ----------

function wanted(what, alt) {
    if (mode[what] == "off") return false;
    if (mode[what] == "on") return alt > 0;
    return alt >= MIN_ALT[what];
}

function round1(x) { return Math.round(x * 10) / 10; }
function wrap180(x) { x = norm360(x); if (x > 180) x = x - 360; return x; }

// Returns the list of segment names to play, and logs why
function plan() {
    var d = daysJ2000();
    var list = ["Intro"];
    var a = moonAlt(d);
    log("Moon alt " + round1(a) + " deg, mode " + mode.Moon);
    if (wanted("Moon", a)) list.push("Moon");
    var up = [];
    for (var i = 0; i < PLANETS.length; i++) {
        a = planetAlt(PLANETS[i], d);
        log(PLANETS[i] + " alt " + round1(a) + " deg, mode " + mode.Planets);
        if (wanted("Planets", a)) up.push(PLANETS[i]);
    }
    if (up.length > 0) {
        list.push("Planets");
        for (i = 0; i < up.length; i++) list.push(up[i]);
        list.push("PlanetsEnd");
    }
    list.push("Stars");
    a = coreAlt(d);
    log("Galactic core alt " + round1(a) + " deg, mode " + mode.Core);
    if (wanted("Core", a)) list.push("Core");
    list.push("Magellan");
    var total = 0;
    for (i = 0; i < list.length; i++) total = total + LEN[list[i]] + GAP;
    log("plan: " + list.join(", ") + " -- about " + Math.round(total) + " s");
    return list;
}

// ---------- functions called by buttons ----------

// Runs the chapter 2 segments; the caller sets running
function distances() {
    var list = plan();
    for (var i = 0; i < list.length; i++) seg(list[i]);
    log("chapter 2 done");
}

// Chapter 2 button
function PlayDistances() {
    running = 1;
    distances();
    running = 0;
}

// Play all button: chapters from number first to 9, one after the other.
// Stop ends it before the next chapter or chapter 2 segment.
function PlayShow(first) {
    running = 1;
    for (var i = first - 1; i < CHAPTERS.length && running; i++) {
        var name = CHAPTERS[i][0];
        log("chapter " + (i + 1) + " " + name);
        if (name == "DistancesAndPerspective") {
            distances();
        } else {
            dm(PAGE + "BSS-VS-" + name + ".Run()");
            waitStep(CHAPTERS[i][1] + GAP);
        }
    }
    if (running) log("show done");
    else log("show stopped");
    running = 0;
}

// Check button: log the plan without playing
function Report() {
    plan();
}

// Toggle buttons: auto, then on, then off, then auto again
function Cycle(what) {
    if (mode[what] == "auto") mode[what] = "on";
    else if (mode[what] == "on") mode[what] = "off";
    else mode[what] = "auto";
    log(what + " is now " + mode[what]);
}

function SetTestOffset(hours) {
    testOffsetHours = hours;
    log("test offset " + hours + " h");
}

// Chapter 7 button: orbit Earth to the point opposite the Moon, moved offset degrees north,
// at altitude alt in metres, with the timing ta:tc:td. Seen from there the Moon hangs just
// above Earth's north limb. Only sends DM commands and returns at once: the button waits.
// The longitude is changed with += by the shortest way round, from the current camera value.
function MoonView(offset, alt, ta, tc, td) {
    var d = daysJ2000();
    var m = moonRaDec(d);
    var gmst = norm360(280.46061837 + 360.98564736629 * d);
    var lon = wrap180(m.ra - gmst + 180);
    var lat = round1(-m.dec + offset);
    var t = " [" + ta + ":" + tc + ":" + td + "]";
    log("Moon RA " + round1(m.ra) + " Dec " + round1(m.dec) + ", camera to lat " + lat + " lon " + round1(lon));
    dm("Scene Camera { Latitude=" + lat + " Altitude=" + alt + " }" + t);
    var cur = NaN;
    try {
        cur = parseFloat(DigitalSky.GetAssetInstance("Camera").GetPropertyInstance("Longitude").Value);
    } catch (e) {
        log("cannot read Camera.Longitude: " + e);
    }
    if (isNaN(cur)) {
        dm("Scene Camera.Longitude=" + round1(lon) + t);
    } else {
        dm("Scene Camera.Longitude+=" + round1(wrap180(lon - cur)) + t);
    }
}

// Stops between segments and chapters; the one already running finishes
function Stop() {
    running = 0;
}

// Values for the toggle-button captions, as $VSMoon, $VSPlanets and $VSCore
function GetMoonMode() { return mode.Moon; }
function GetPlanetsMode() { return mode.Planets; }
function GetCoreMode() { return mode.Core; }
DigitalSky.AddVariable("VSMoon", "GetMoonMode");
DigitalSky.AddVariable("VSPlanets", "GetPlanetsMode");
DigitalSky.AddVariable("VSCore", "GetCoreMode");
